style.css:
@-moz-document domain("roblox.com") {
html, body {
    margin: 0 !important;
    min-height: 100% !important;
    background:
      radial-gradient(circle at 20% 15%, rgba(96, 165, 250, 0.35), transparent 22%),
      radial-gradient(circle at 85% 25%, rgba(250, 204, 21, 0.18), transparent 16%),
      radial-gradient(circle at 50% 85%, rgba(29, 78, 216, 0.30), transparent 28%),
      linear-gradient(135deg, #020617 0%, #081226 40%, #1d4ed8 100%) !important;
    background-attachment: fixed !important;
    color: #f8fafc !important;
    overflow-x: hidden !important;
  }

  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background:
      repeating-linear-gradient(
        115deg,
        rgba(255, 255, 255, 0.05) 0,
        rgba(255, 255, 255, 0.05) 2px,
        transparent 2px,
        transparent 28px
      );
    opacity: 0.22;
    z-index: 0;
  }

  body::after {
    content: "";
    position: fixed;
    right: 7%;
    top: 12%;
    width: 130px;
    height: 130px;
    border-radius: 50%;
    border: 10px solid #facc15;
    box-shadow: 0 0 24px rgba(250, 204, 21, 0.75);
    pointer-events: none;
    z-index: 0;
  }

  .game-home-page-container,
  .home-container,
  .container-main,
  .content,
  #rbx-body {
    background: transparent !important;
    position: relative !important;
    z-index: 1 !important;
  }

  .game-home-page-container,
  .home-container {
    padding-top: 10px !important;
  }

  .nav-header,
  .rbx-navbar,
  [class*="header"] {
    background: rgba(2, 6, 23, 0.88) !important;
    border-bottom: 1px solid rgba(96, 165, 250, 0.18) !important;
    box-shadow: 0 0 18px rgba(59, 130, 246, 0.25) !important;
  }

  .home-page-game-section,
  .game-home-page-container > div,
  [class*="section"],
  [class*="Section"],
  [class*="card"],
  [class*="Card"],
  [class*="panel"],
  [class*="Panel"] {
    background: rgba(2, 6, 23, 0.62) !important;
    border: 1px solid rgba(96, 165, 250, 0.16) !important;
    border-radius: 20px !important;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.32) !important;
  }

  .game-carousel,
  [class*="carousel"] {
    background: transparent !important;
  }

  a,
  .text-link,
  .rbx-text {
    color: #93c5fd !important;
  }

  h1, h2, h3, h4, h5 {
    color: #ffffff !important;
    text-shadow: 0 0 8px rgba(96, 165, 250, 0.35) !important;
  }

  .input-field,
  .rbx-input,
  input[type="text"],
  input[type="search"] {
    background: rgba(15, 23, 42, 0.92) !important;
    color: #f8fafc !important;
    border: 1px solid rgba(96, 165, 250, 0.25) !important;
    border-radius: 14px !important;
  }

  .btn-primary-md,
  .btn-primary-lg,
  .btn-control-md,
  .buy-button,
  .play-button,
  .action-button {
    background: linear-gradient(90deg, #1d4ed8, #60a5fa) !important;
    color: white !important;
    border: none !important;
    border-radius: 999px !important;
    box-shadow: 0 0 18px rgba(96, 165, 250, 0.35) !important;
  }

  .btn-primary-md:hover,
  .btn-primary-lg:hover,
  .btn-control-md:hover,
  .buy-button:hover,
  .play-button:hover,
  .action-button:hover {
    transform: translateY(-2px) scale(1.03) !important;
    box-shadow: 0 0 28px rgba(96, 165, 250, 0.58) !important;
  }

  img,
  .thumbnail-2d-container img,
  .game-card-thumb {
    filter: drop-shadow(0 0 8px rgba(96, 165, 250, 0.24)) !important;
  }
}
